import React, { useState } from "react";
import { NavLink } from "react-router-dom";
import "./Routes.css";

import Navbar from "../../components/Navbar/Navbar";
import Footer from "../../components/Footer/Footer";

import douala from "../../assets/routes/douala.jpg";
import yaounde from "../../assets/routes/yaounde.jpg";
import bamenda from "../../assets/routes/bamenda.jpg";
import limbe from "../../assets/routes/limbe.jpg";

function Routes() {
  const [search, setSearch] = useState("");

  const filteredRoutes = routes.filter((route) =>
    `${route.from} ${route.to}`
      .toLowerCase()
      .includes(search.toLowerCase())
  );

  return (
    <>
      <Navbar />

      <section className="routes-hero">
        <div className="hero-overlay">
          <h1>Available Bus Routes</h1>
          <p>Find your perfect journey across Cameroon.</p>
        </div>
      </section>

      <section className="routes-container">

        <div className="search-box">
          <input
            type="text"
            placeholder="Search by departure or destination..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        <div className="route-grid">
          {filteredRoutes.map((route) => (
            <div className="route-card" key={route.id}>

              <img src={route.image} alt={route.to} />

              <div className="route-content">

                <h2>
                  {route.from} → {route.to}
                </h2>

                <div className="route-details">

                  <span>🕒 {route.duration}</span>

                  <span>{route.type}</span>

                </div>

                <h3>XAF {route.price.toLocaleString()}</h3>

                <NavLink to="/booking">
                <button>Book Now</button></NavLink>

              </div>

            </div>
          ))}

          {filteredRoutes.length === 0 && (
            <h2 className="no-results">
                No routes found.
                </h2>
            )}
        </div>

      </section>

      <Footer />
    </>
  );
}

export default Routes;
